-- Seed: 38 verified target accounts (docs/research/02-target-accounts.md §1.1) and the first 15
-- outreach hooks (§5) as leads in stage 'identified'. Idempotent: accounts upsert on name; a lead
-- is created only if the account has no lead yet. Domains are derived only from evidence URLs on
-- the company's own site; everything else stays null until verified. No outreach is sent from here.
set search_path to ps, public;

on conflict (name) do update set
  domain = coalesce(ps.accounts.domain, excluded.domain),
  country = excluded.country, segment = excluded.segment, priority = excluded.priority,
  why_they_care = excluded.why_they_care, evidence_urls = excluded.evidence_urls;

-- First 15 hooks (§5 ranking). One factual sentence + evidence URL; source and legitimate-interest
-- rationale recorded per §4.9. Contact is null until a public B2B path is verified (§4).
with hooks(rank, account, hook, url) as (values
 (1,  $$Niron Magnetics$$, $$Niron's Sartell, MN plant received a conditional US$150M, 20-year loan commitment from the Office of Strategic Capital on 7 Aug 2026, with the plant due to be operational in 2027.$$, 'https://www.war.gov/News/Releases/Release/Article/4566567/office-of-strategic-capital-signs-150-million-conditional-loan-commitment-with/'),
 (2,  $$General Motors$$, $$GM signed a multi-year agreement with Noveon Magnetics in Aug 2025 for American-made rare-earth magnets while remaining an investor in rare-earth-free Niron.$$, 'https://www.prnewswire.com/news-releases/driving-american-industry-general-motors--noveon-magnetics-sign-multi-year-agreement-to-deliver-american-made-rare-earth-magnets-302522804.html'),
 (3,  $$Stellantis$$, $$Stellantis and Niron Magnetics announced a partnership on rare-earth-free electric-motor technology, in addition to Stellantis Ventures' stake in Niron's US$33M round.$$, 'https://autotechinsight.spglobal.com/news/5284624/niron-magnetics-partners-with-stellantis-for-rare-earth-free-electric-motor-technology'),
 (4,  $$Honda Motor$$, $$Honda invested in Niron Magnetics in 2025, becoming the newest automaker to back iron-nitride magnets.$$, 'https://www.manufacturingdive.com/news/honda-invests-in-us-maker-of-rare-earth-free-magnets/830283/'),
 (5,  $$Proterial$$, $$Proterial announced a heavy-rare-earth-free NdFeB sintered magnet for EV drive motors on 22 July 2025, alongside its ferrite (NMF) prototype EV motor.$$, 'https://www.proterial.com/e/press/2025/n0722b.html'),
 (6,  $$Vacuumschmelze (VAC) / eVAC Magnetics$$, $$VAC launched VACODYM 902 TP, a heavy-rare-earth-free NdFeB grade, and opened the DoD-funded eVAC plant in Sumter, SC in July.$$, 'https://vacuumschmelze.com/Newsroom/vacodym-902-tp-heavy-rare-earth-free-permanent-magnets-n2833'),
 (7,  $$ZF Friedrichshafen$$, $$ZF presented the I2SM, an in-rotor inductively excited synchronous motor with no magnets, as a production-ready alternative with up to 50% lower CO2 footprint than a PSM.$$, 'https://press.zf.com/press/en/releases/release_60480.html'),
 (8,  $$MAHLE$$, $$MAHLE positioned its SCT + MCT combination as the "perfect motor", explicitly citing the absence of rare earths in the magnet-free MCT design.$$, 'https://newsroom.mahle.com/press/en/press-releases/perfect-motor-mahle-combines-strengths-of-its-sct-and-mct-electric-motors-99968'),
 (9,  $$Renault Group / Ampere$$, $$Renault ended the E7A rare-earth-free motor collaboration with Valeo in 2025 and is considering a Chinese stator supplier while developing in-house.$$, 'https://www.marketscreener.com/news/renault-may-develop-new-rare-earth-free-motor-with-chinese-supplier-ce7d5fd8da8ff226'),
 (10, $$BMW Group$$, $$BMW's Gen6 eDrive for the Neue Klasse keeps the electrically excited synchronous motor with no rare-earth magnets, now on an 800V architecture.$$, 'https://www.emobility-engineering.com/bmw-gen6-two-motor-800v-edrive-cylindrical-battery/'),
 (11, $$Toyota Motor$$, $$Toyota's neodymium-reduced magnet substitutes lanthanum and cerium for up to 50% of the neodymium and eliminates dysprosium and terbium, targeting drive motors, EPS and appliances.$$, 'https://global.toyota/en/newsroom/corporate/21139684.html'),
 (12, $$Hitachi Astemo$$, $$Hitachi Astemo announced a new rare-earth-free motor in its 27 Oct 2025 release.$$, 'https://www.astemo.com/en/news/20251027-01/'),
 (13, $$Noveon Magnetics$$, $$Noveon Magnetics, the only operational US sintered NdFeB maker, signed supply agreements with GM, ABB and Nidec, so rare-earth-free substitutes directly threaten its addressable market.$$, 'https://noveon.co/general-motors-noveon-magnetics-sign-multi-year-agreement'),
 (14, $$TDK$$, $$TDK markets the FB series, the world's first La-Co high-performance ferrite, and runs one of the largest ferrite magnet operations globally.$$, 'https://product.tdk.com/en/products/magnet/magnet/ferrite/index.html'),
 (15, $$Arnold Magnetic Technologies$$, $$Arnold Magnetic Technologies produces ARNOX hard ferrite and RECOMA SmCo magnets under ITAR/DFARS compliance for defense customers.$$, 'https://www.arnoldmagnetics.com/')
)
select a.id, 'identified', 'prospecting',
  'Verify a public B2B contact path (attorney of record / IP page / press contact) before any outreach; blocked until outreach domain, mailbox and legal/REVIEW_STATUS.md allow it.',
  format(E'Outreach rank: %s of 15 (docs/research/02-target-accounts.md §5).\nHook: %s\nEvidence: %s\nSource of account: desk research 2026-09-25 (public press releases and trade media).\nLawful basis: legitimate interest, B2B, role-relevant (IP / R&D / strategy). Opt-out honoured via ps.do_not_contact.', h.rank, h.hook, h.url)
from hooks h join ps.accounts a on a.name = h.account
where not exists (select 1 from ps.leads l where l.account_id = a.id);
